  IF EXISTS (SELECT 1 FROM public.organizations WHERE slug IN ('jnr-engineering', 'marpet')) THEN
    RAISE EXCEPTION 'This database holds real companies. Preview test data goes only into the separate test project.';
  END IF;
END
$$;

